interface HeroImageProps {
  src: string;
  alt: string;
  fill?: boolean;
  priority?: boolean;
  sizes: string;
  className?: string;
}

function variantUrl(src: string, width: number) {
  const stem = src.replace(/^\/imgs\//, '').replace(/\.[^.]+$/, '');
  return `/imgs/optimized/${stem}-${width}.webp`;
}

// Static exports cannot use Next's image server. Variants are generated by npm run optimize:images.
export default function HeroImage({ src, alt, fill, priority, sizes, className }: HeroImageProps) {
  return (
    // eslint-disable-next-line @next/next/no-img-element
    <img
      src={variantUrl(src, 1280)}
      srcSet={[640, 1280, 1920].map(width => `${variantUrl(src, width)} ${width}w`).join(', ')}
      sizes={sizes}
      alt={alt}
      width={fill ? undefined : 1280}
      height={fill ? undefined : 720}
      loading={priority ? 'eager' : 'lazy'}
      fetchPriority={priority ? 'high' : undefined}
      decoding="async"
      className={className}
      style={fill ? { position: 'absolute', inset: 0, width: '100%', height: '100%' } : undefined}
    />
  );
}
